mapper.update:
UPDATE shopwizard.tShpShipDirect SET
    SalePrice = #{salePrice}, SupplyPrice = #{supplyPrice}, BuyPrice = #{buyPrice}, VatAmt = #{vatAmt},
    CustChrgDeliFee = #{deliFeeAmt}, DeliFeeType = #{deliFeeType}, DeliFeeAmt = #{deliFeeAmt}, PromotFeeAmt = #{promotFeeAmt},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo} AND OrderProdNo = #{orderProdNo} AND ProdQty = #{prodQty}

UPDATE shopwizard.tShpReturnDirect SET
    SalePrice = #{salePrice}, SupplyPrice = #{supplyPrice}, BuyPrice = #{buyPrice}, VatAmt = #{vatAmt},
    DeliFeeType = #{deliFeeType}, DeliFeeAmt = #{deliFeeAmt}, PromotFeeAmt = #{promotFeeAmt},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo} AND OrderProdNo = #{orderProdNo} AND ProdQty = #{prodQty}

UPDATE shopwizard.tAdjAdjustDetail SET
    SalePrice = #{salePrice}, SupplyPrice = #{supplyPrice}, BuyPrice = #{buyPrice}, VatAmt = #{vatAmt},
    CustChrgDeliFee = #{deliFeeAmt}, DeliFeeType = #{deliFeeType}, DeliFeeAmt = #{deliFeeAmt}, PromotFeeAmt = #{promotFeeAmt},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo} AND OrderProdNo = #{orderProdNo} AND ProdQty = #{prodQty}
  AND BuyAdjustCloseDate IS NULL AND AdjustNo IS NULL AND SaleAdjustCloseDate IS NULL AND SaleAdjustNo IS NULL

UPDATE shopwizard.tAdjAdjustDetail SET
    SalePrice = -1 * #{salePrice}, SupplyPrice = -1 * #{supplyPrice}, BuyPrice = -1 * #{buyPrice}, VatAmt = -1 * #{vatAmt},
    DeliFeeType = #{deliFeeType}, DeliFeeAmt = -1 * #{deliFeeAmt}, PromotFeeAmt = #{promotFeeAmt},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo} AND OrderProdNo = #{orderProdNo} AND ProdQty = -1 * #{prodQty}
  AND BuyAdjustCloseDate IS NULL AND AdjustNo IS NULL AND SaleAdjustCloseDate IS NULL AND SaleAdjustNo IS NULL
